using System.Diagnostics;
using System.Reflection;
using System.Runtime.Loader;
using System.Security.Cryptography;
using System.Text.Json;
string[] names={"OfficeIMO_Read","ExcelReaderNet_Read","Sylvan_Read","ExcelDataReader_Read","OfficeIMO_Parse","ExcelReaderNet_Parse"};
using var baseline=new Fixture(args[0],names);
using var candidate=new Fixture(args[1],names);
foreach(string name in names)if(baseline.Methods[name]()!=candidate.Methods[name]())throw new Exception("Different checksum: "+name);
const int warmups=8, rounds=12, blockOperations=8;
for(int round=0;round<warmups;round++)for(int j=0;j<names.Length;j++) {
 string name=names[(j+round)%names.Length];
 for(int i=0;i<blockOperations;i++)baseline.Methods[name]();
 for(int i=0;i<blockOperations;i++)candidate.Methods[name]();
}
var rows=new List<object>();
for(int round=0;round<rounds;round++)for(int j=0;j<names.Length;j++) {
 string name=names[(j+round)%names.Length];
 string[] order=round%2==0?new[]{"baseline","candidate","candidate","baseline"}:new[]{"candidate","baseline","baseline","candidate"};
 for(int block=0;block<4;block++) {
  string lane=order[block];var action=(lane=="baseline"?baseline:candidate).Methods[name];
  long allocatedBefore=GC.GetTotalAllocatedBytes(true);var watch=Stopwatch.StartNew();
  for(int i=0;i<blockOperations;i++)action();
  watch.Stop();long allocated=GC.GetTotalAllocatedBytes(true)-allocatedBefore;
  rows.Add(new{round,method=name,block,lane,operations=blockOperations,nanosecondsPerOperation=watch.Elapsed.TotalNanoseconds/blockOperations,allocatedBytesPerOperation=allocated/(double)blockOperations});
 }
}
Console.WriteLine(JsonSerializer.Serialize(new{warmups,rounds,blockOperations,baseline=baseline.Identity,candidate=candidate.Identity,blocks=rows,protocol="Two isolated assembly contexts, identical validated workload and harness; sequentialABBA/BAAB blocks,rotatedcaseorder,nooutlierremoval. Per-lane round sample is mean of its two8operation blocks. Reflection/delegate binding and full-field preflight outside timing. One delegate call per complete operation, no per-cell adapter. GC.GetTotalAllocatedBytes precise includes all threads. No concurrent engine work."}));
sealed class Context(string root):AssemblyLoadContext(isCollectible:false) {
 readonly AssemblyDependencyResolver resolver=new(Path.Combine(Path.GetFullPath(root),"OfficeIMO.Excel.Benchmarks.dll"));
 protected override Assembly? Load(AssemblyName name){string? path=resolver.ResolveAssemblyToPath(name);return path==null?null:LoadFromAssemblyPath(path);}
 protected override nint LoadUnmanagedDll(string name){string? path=resolver.ResolveUnmanagedDllToPath(name);return path==null?0:LoadUnmanagedDllFromPath(path);}
}
sealed class Fixture:IDisposable {
 readonly object instance; readonly Action cleanup; readonly Context context;
 internal Dictionary<string,Func<long>> Methods {get;}=new();
 internal object Identity {get;}
 internal Fixture(string root,string[] names) {
  root=Path.GetFullPath(root);context=new Context(root);
  var assembly=context.LoadFromAssemblyPath(Path.Combine(root,"OfficeIMO.Excel.Benchmarks.dll"));
  var type=assembly.GetType("OfficeIMO.Excel.Benchmarks.ExcelReaderGeneratedBenchmarks",true)!;
  instance=Activator.CreateInstance(type)!;
  var format=type.GetProperty("Format")!;format.SetValue(instance,Enum.Parse(format.PropertyType,"Xlsx"));
  type.GetProperty("RowCount")!.SetValue(instance,50000);
  cleanup=(Action)type.GetMethod("Cleanup")!.CreateDelegate(typeof(Action),instance);
  try { ((Action)type.GetMethod("Setup")!.CreateDelegate(typeof(Action),instance))();foreach(string name in names)Methods[name]=(Func<long>)type.GetMethod(name)!.CreateDelegate(typeof(Func<long>),instance); }
  catch { cleanup();throw; }
  string Hash(string name)=>Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(Path.Combine(root,name))));
  Identity=new{engineSha256=Hash("OfficeIMO.Excel.dll"),harnessSha256=Hash("OfficeIMO.Excel.Benchmarks.dll"),coreSha256=Hash("OfficeIMO.Core.dll")};
 }
